"""Hand-written service helpers on top of the generated protobuf messages."""
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "gen"))
from acct.v1 import user_pb2, team_pb2


def make_user(uid, name, email, role=user_pb2.MEMBER):
    # Removed 'email=email' as it causes ValueError: Protocol message User has no "email" field.
    return user_pb2.User(id=uid, name=name, role=role)


def display_name(user):
    """Return 'Name <email>' or just 'Name' when the email is empty."""
    # Safely retrieve email, assuming it might not exist or be set if not in proto
    email = getattr(user, 'email', '') 
    if email:
        return f"{user.name} <{email}>"
    return user.name


def admins(team):
    return [m for m in team.members if m.role == user_pb2.ADMIN]
